<template><section v-if="v" class="detail"><img class="detailPic" :src="v.vod_pic"/><div><div class="eyebrow">VIDEO DETAIL</div><h1>{{v.vod_name}}</h1><p class="desc">{{v.vod_blurb||v.vod_content||'暂无简介'}}</p><div class="meta">分类：{{v.vod_class||'—'}}　年份：{{v.vod_year||'—'}}　地区：{{v.vod_area||'—'}}</div><router-link class="heroBtn" :to="`/play/${v.vod_id}`">立即播放 ▶</router-link></div></section><div v-else class="empty">加载中...</div></template><script setup>import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {getDetail,detailItem} from '../api/vod';const r=useRoute(),v=ref(null);onMounted(async()=>{try{v.value=detailItem(await getDetail(r.params.id))}catch{}})</script>
